//! OST's text in the app language: one translator for the desktop's QML
//! (its QTranslator asks this one), the desktop's Rust and the engine.
//!
//! Every string OST shows is written in English in the code (`tr("…")` in
//! Rust, `qsTr("…")` in QML) and keyed to the Teams string id whose en-us
//! text it is (desktop/i18n/ids.json, generated by desktop/i18n/l10n.py).
//! The catalogue of Teams' own translations, built on the device from
//! Teams' string resources (api::teams_strings), maps each id to its text
//! in Qt's form: `%1`, `%2`… for Teams' placeholders in their en-us order,
//! `%n` for a count, and a plural message as its forms
//! (`{"=1": …, "one": …, "other": …}`), picked as Teams' ICU messages pick
//! them: an exact `=N` form first, else the language's CLDR category.
//!
//! Until [`install`] runs (the TUI, tests, an app language whose strings
//! couldn't be had) every string reads as its English, plural forms
//! included.

use std::collections::HashMap;
use std::sync::{Arc, RwLock};

use serde_json::Value;

struct Catalogue {
    index: HashMap<String, usize>,
    rows: Vec<Value>,
    /// The plural-rule language ("de", "pt-br").
    lang: String,
    /// The digits a count is written in (Teams formats `#` in its
    /// language's own numbering system: Arabic-Indic for ar, Persian for fa).
    zero: char,
}

static CATALOGUE: RwLock<Option<Arc<Catalogue>>> = RwLock::new(None);

fn key(source: &str, dis: &str) -> String {
    if dis.is_empty() {
        source.to_string()
    } else {
        format!("{source}\u{4}{dis}")
    }
}

/// OST's strings keyed to Teams' ids (desktop/i18n/ids.json).
pub const IDS: &str = include_str!("../desktop/i18n/ids.json");

/// Install OST's strings in `locale` (one of Teams' string locales,
/// "de-de"): `catalogue` is the built catalogue's JSON (`{"strings": {id:
/// …}}`), none for en-us (OST's own English plural forms then).
pub fn install(catalogue: Option<&str>, locale: &str) -> anyhow::Result<()> {
    let cat = Catalogue::new(IDS, catalogue, locale)?;
    *CATALOGUE.write().unwrap() = Some(Arc::new(cat));
    Ok(())
}

impl Catalogue {
fn new(ids: &str, catalogue: Option<&str>, locale: &str) -> anyhow::Result<Self> {
    let strings = match catalogue {
        Some(c) => {
            let v: Value = serde_json::from_str(c)?;
            match v.get("strings") {
                Some(Value::Object(m)) if !m.is_empty() => m.clone(),
                _ => anyhow::bail!("catalogue has no strings"),
            }
        }
        None => serde_json::Map::new(),
    };
    let rows_in: Vec<Vec<Value>> = serde_json::from_str(ids)?;
    let mut index = HashMap::with_capacity(rows_in.len() * 2);
    let mut rows = Vec::with_capacity(rows_in.len());
    for (i, r) in rows_in.iter().enumerate() {
        let s = |k: usize| r.get(k).and_then(Value::as_str).unwrap_or_default();
        let (source, dis, id) = (s(0), s(1), s(2));
        // Teams' translation, else OST's English plural forms.
        rows.push(strings.get(id).cloned().or_else(|| r.get(4).cloned()).unwrap_or(Value::Null));
        index.insert(key(source, dis), i);
        // the id names the string too: tr_id("…", "<ns>:<key>")
        index.insert(key(source, id), i);
    }
    let base = locale.split('-').next().unwrap_or_default();
    let lang = if locale == "pt-br" { "pt-br".to_string() } else { base.to_string() };
    let zero = match base {
        "ar" => '\u{660}',
        "fa" => '\u{6f0}',
        _ => '0',
    };
    Ok(Catalogue { index, rows, lang, zero })
}

fn lookup(&self, source: &str, dis: &str, n: Option<i64>) -> Option<String> {
    let i = self.index.get(&key(source, dis)).or_else(|| (!dis.is_empty()).then(|| self.index.get(source)).flatten())?;
    let text = match &self.rows[*i] {
        Value::String(s) => s.clone(),
        Value::Object(forms) => {
            let count = n.unwrap_or(0);
            let pick = forms
                .get(&format!("={count}"))
                .or_else(|| forms.get(plural_category(&self.lang, count.unsigned_abs())))
                .or_else(|| forms.get("other"))?;
            pick.as_str()?.to_string()
        }
        _ => return None,
    };
    Some(match n {
        Some(n) => text.replace("%n", &number_in(n, self.zero)),
        None => text,
    })
}
}

fn current() -> Option<Arc<Catalogue>> {
    let installed = CATALOGUE.read().unwrap().clone();
    match installed {
        Some(c) => Some(c),
        None => {
            install(None, "en-us").ok()?;
            CATALOGUE.read().unwrap().clone()
        }
    }
}

/// The app language's text for `source` (its disambiguation or Teams id
/// `dis`), `%n` written as `n` when given; None when OST has no such
/// string (it reads as its English).
pub fn lookup(source: &str, dis: &str, n: Option<i64>) -> Option<String> {
    current()?.lookup(source, dis, n)
}

fn number_in(n: i64, zero: char) -> String {
    let s = n.to_string();
    if zero == '0' {
        return s;
    }
    s.chars()
        .map(|c| c.to_digit(10).and_then(|d| char::from_u32(zero as u32 + d)).unwrap_or(c))
        .collect()
}

/// A count in the app language's digits ("11", "١١" in Arabic).
pub fn number(n: i64) -> String {
    let zero = current().map_or('0', |c| c.zero);
    number_in(n, zero)
}

/// `source` in the app language: Teams' wording where OST has the string,
/// else the English.
pub fn tr(source: &str) -> String {
    lookup(source, "", None).unwrap_or_else(|| source.to_string())
}

/// `tr` for a count: `%n` is the number, and the plural form the
/// language's for it.
pub fn tr_n(source: &str, n: i64) -> String {
    lookup(source, "", Some(n)).unwrap_or_else(|| source.replace("%n", &n.to_string()))
}

/// `tr` naming the Teams string explicitly (`"<namespace>:<key>"`), where
/// Teams has several strings with the same English.
pub fn tr_id(source: &str, id: &str) -> String {
    lookup(source, id, None).unwrap_or_else(|| source.to_string())
}

/// `tr_n` naming the Teams string explicitly.
pub fn tr_id_n(source: &str, id: &str, n: i64) -> String {
    lookup(source, id, Some(n)).unwrap_or_else(|| source.replace("%n", &n.to_string()))
}

/// A translated text's placeholders `%1`…`%9` filled with `args`, in one
/// pass (an argument holding "%2" stays as it is).
pub fn fill(text: &str, args: &[&str]) -> String {
    let mut out = String::with_capacity(text.len() + args.iter().map(|a| a.len()).sum::<usize>());
    let mut chars = text.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '%'
            && let Some(d) = chars.peek().and_then(|d| d.to_digit(10))
            && d >= 1
            && let Some(a) = args.get(d as usize - 1)
        {
            chars.next();
            out.push_str(a);
            continue;
        }
        out.push(c);
    }
    out
}

/// CLDR's cardinal plural category of a whole number in Teams' string
/// languages (what Teams' ICU messages pick a form by).
pub fn plural_category(lang: &str, n: u64) -> &'static str {
    let (m10, m100) = (n % 10, n % 100);
    let within = |v: u64, a: u64, b: u64| v >= a && v <= b;
    match lang {
        "ar" => match n {
            0 => "zero",
            1 => "one",
            2 => "two",
            _ if within(m100, 3, 10) => "few",
            _ if within(m100, 11, 99) => "many",
            _ => "other",
        },
        "cy" => match n {
            0 => "zero",
            1 => "one",
            2 => "two",
            3 => "few",
            6 => "many",
            _ => "other",
        },
        "he" => match n {
            1 => "one",
            2 => "two",
            _ => "other",
        },
        "ru" | "uk" => {
            if m10 == 1 && m100 != 11 {
                "one"
            } else if within(m10, 2, 4) && !within(m100, 12, 14) {
                "few"
            } else {
                "many"
            }
        }
        "bs" | "hr" | "sr" => {
            if m10 == 1 && m100 != 11 {
                "one"
            } else if within(m10, 2, 4) && !within(m100, 12, 14) {
                "few"
            } else {
                "other"
            }
        }
        "pl" => {
            if n == 1 {
                "one"
            } else if within(m10, 2, 4) && !within(m100, 12, 14) {
                "few"
            } else {
                "many"
            }
        }
        "cs" | "sk" => match n {
            1 => "one",
            2..=4 => "few",
            _ => "other",
        },
        "lt" => {
            if m10 == 1 && !within(m100, 11, 19) {
                "one"
            } else if within(m10, 2, 9) && !within(m100, 11, 19) {
                "few"
            } else {
                "other"
            }
        }
        "lv" => {
            if m10 == 0 || within(m100, 11, 19) {
                "zero"
            } else if m10 == 1 && m100 != 11 {
                "one"
            } else {
                "other"
            }
        }
        "ro" => {
            if n == 1 {
                "one"
            } else if n == 0 || within(m100, 2, 19) {
                "few"
            } else {
                "other"
            }
        }
        "sl" => match m100 {
            1 => "one",
            2 => "two",
            3 | 4 => "few",
            _ => "other",
        },
        "mt" => {
            if n == 1 {
                "one"
            } else if n == 2 {
                "two"
            } else if n == 0 || within(m100, 3, 10) {
                "few"
            } else if within(m100, 11, 19) {
                "many"
            } else {
                "other"
            }
        }
        "mk" | "is" => {
            if m10 == 1 && m100 != 11 {
                "one"
            } else {
                "other"
            }
        }
        "fr" | "pt-br" => {
            if n == 0 || n == 1 {
                "one"
            } else if n % 1_000_000 == 0 {
                "many"
            } else {
                "other"
            }
        }
        "es" | "it" | "ca" | "pt" => {
            if n == 1 {
                "one"
            } else if n != 0 && n % 1_000_000 == 0 {
                "many"
            } else {
                "other"
            }
        }
        "hi" | "fa" => {
            if n <= 1 {
                "one"
            } else {
                "other"
            }
        }
        "fil" => {
            if within(n, 1, 3) || !matches!(m10, 4 | 6 | 9) {
                "one"
            } else {
                "other"
            }
        }
        "ja" | "ko" | "zh" | "th" | "vi" | "id" | "ms" | "lo" | "km" => "other",
        _ => {
            if n == 1 {
                "one"
            } else {
                "other"
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    const TEST_IDS: &str = r#"[["Call ended","","calling:ka",[]],["%1 added %2 to the chat.","messaging:kb","messaging:kb",["<0>","<1>"]],["%n others","","messaging:kc_mf",[],{"one":"%n other","other":"%n others"}],["%1 added %2 to the chat.","","messaging:kd",["initiator","targetOne"]]]"#;

    #[test]
    fn teams_wording_with_english_fallback() {
        let en = Catalogue::new(TEST_IDS, None, "en-us").unwrap();
        let t = |c: &Catalogue, s: &str, d: &str, n: Option<i64>| c.lookup(s, d, n);
        assert_eq!(t(&en, "Call ended", "", None), None);
        // OST's English plural forms need no catalogue
        assert_eq!(t(&en, "%n others", "", Some(1)).unwrap(), "1 other");
        assert_eq!(t(&en, "%n others", "", Some(3)).unwrap(), "3 others");
        let cat = r#"{"strings":{"calling:ka":"Anruf beendet","messaging:kb":"%1 hat %2 zum Chat hinzugefügt.","messaging:kc_mf":{"one":"%n weitere Person","other":"%n weitere Personen"}}}"#;
        let de = Catalogue::new(TEST_IDS, Some(cat), "de-de").unwrap();
        assert_eq!(t(&de, "Call ended", "", None).unwrap(), "Anruf beendet");
        assert_eq!(fill(&t(&de, "%1 added %2 to the chat.", "messaging:kb", None).unwrap(), &["Ann", "Bo %1"]), "Ann hat Bo %1 zum Chat hinzugefügt.");
        // the same English under another id Teams hasn't translated: English
        assert_eq!(t(&de, "%1 added %2 to the chat.", "", None), None);
        assert_eq!(t(&de, "%n others", "", Some(1)).unwrap(), "1 weitere Person");
        assert_eq!(t(&de, "%n others", "", Some(4)).unwrap(), "4 weitere Personen");
        assert_eq!(t(&de, "Not OST's", "", None), None);
        let cat = r#"{"strings":{"messaging:kc_mf":{"one":"%n آخر","two":"اثنان آخران","few":"%n آخرين","other":"%n آخر"}}}"#;
        let ar = Catalogue::new(TEST_IDS, Some(cat), "ar-sa").unwrap();
        assert_eq!(t(&ar, "%n others", "", Some(2)).unwrap(), "اثنان آخران");
        assert_eq!(t(&ar, "%n others", "", Some(11)).unwrap(), "١١ آخر");
        assert_eq!(t(&ar, "%n others", "", Some(5)).unwrap(), "٥ آخرين");
        assert_eq!(number_in(2026, ar.zero), "٢٠٢٦");
        assert!(Catalogue::new(TEST_IDS, Some(r#"{"strings":{}}"#), "de-de").is_err());
    }

    #[test]
    fn english_by_default() {
        // nothing installed in tests: OST's English, plural forms included
        assert_eq!(tr("Call ended"), "Call ended");
        assert_eq!(tr_id_n("%n others", "messaging:k7xsi91tl_mf", 1), "1 other");
        assert_eq!(tr_id_n("%n others", "messaging:k7xsi91tl_mf", 2), "2 others");
    }

    #[test]
    fn plural_categories() {
        assert_eq!(plural_category("ar", 0), "zero");
        assert_eq!(plural_category("ar", 103), "few");
        assert_eq!(plural_category("ar", 111), "many");
        assert_eq!(plural_category("ru", 21), "one");
        assert_eq!(plural_category("ru", 12), "many");
        assert_eq!(plural_category("pl", 22), "few");
        assert_eq!(plural_category("fr", 0), "one");
        assert_eq!(plural_category("de", 0), "other");
        assert_eq!(plural_category("ja", 1), "other");
    }

    #[test]
    fn fill_is_one_pass() {
        assert_eq!(fill("%2 vor %1", &["a", "b"]), "b vor a");
        assert_eq!(fill("100% %1", &["x"]), "100% x");
        assert_eq!(fill("%3", &["x"]), "%3");
    }
}
